COOLBASH_MSG['un ~/.bashrc autonome compilé — réglages et modules inlinés, aucune lecture de ~/.coolbash au chargement, régénéré par coolbash update ; se copie tel quel sur un serveur']='a compiled standalone ~/.bashrc — settings and modules inlined, nothing read from ~/.coolbash at load time, regenerated by coolbash update; copies as is to a server'
COOLBASH_MSG['Récapitulatif']='Summary'
COOLBASH_MSG['Tout est au réglage par défaut : rien à écrire, seule la version est notée.']='Everything is at its default: nothing to write, only the version is recorded.'
COOLBASH_MSG['\n\e[32m[CoolBash]\e[0m écrit : %s\n']='\n\e[32m[CoolBash]\e[0m written: %s\n'
COOLBASH_MSG["\e[32m[CoolBash]\e[0m %s repasse en mode source (l'ancien est gardé à côté)\n"]='\e[32m[CoolBash]\e[0m %s goes back to source mode (the old one is kept next to it)\n'
COOLBASH_MSG['Recharge : source ~/.bashrc (ou ouvre un terminal).']='Reload: source ~/.bashrc (or open a terminal).'
